// Simula una BD con lista en memoria para poder ejecutar
import javax.persistence.Entity;
import javax.persistence.Id;
import javax.persistence.GeneratedValue;
import javax.persistence.GenerationType;
import javax.persistence.EntityManager;
import javax.persistence.EntityManagerFactory;
import javax.persistence.Persistence;

// Define la entidad 'Producto'
@Entity
public class Producto {
  @Id
  @GeneratedValue(strategy = GenerationType.IDENTITY)
  private Long id;
  private String nombre;
  private Double precio;

  // Getters y setters
  public Long getId() {
    return id;
  }

  public void setId(Long id) {
    this.id = id;
  }

  public String getNombre() {
    return nombre;
  }

  public void setNombre(String nombre) {
    this.nombre = nombre;
  }

  public Double getPrecio() {
    return precio;
  }

  public void setPrecio(Double precio) {
    this.precio = precio;
  }
}

public class Main {
  public static void main(String[] args) {
    // Crea un EntityManager
    EntityManagerFactory emf = Persistence.createEntityManagerFactory("mi-unidad-de-persistencia");
    EntityManager em = emf.createEntityManager();

    // Crea un nuevo producto
    Producto producto = new Producto();
    producto.setNombre("Producto 1");
    producto.setPrecio(10.99);

    // Lo guarda en la base de datos
    em.getTransaction().begin();
    em.persist(producto);
    em.getTransaction().commit();

    // Cierra el EntityManager
    em.close();
    emf.close();
  }
}

